EXTRA={  # subject_id: (topic, [quiz], [resources], [conceptIds])
"e-tok":(T("e-tok-x1","Context engineering and token economics","Context engineering decides what goes into each call and in what order. Treat the window as a budget: reserve output tokens, then fixed costs (system prompt, tool schemas), then split the rest among retrieved evidence, conversation history and memory by priority. Put stable content first so prompt caching hits. When history overflows, compress older turns into summaries, drop stale tool outputs, and keep identifiers verbatim. Measure cost per task, not per call, because agents make many calls and input tokens dominate the bill.",["Context assembly order and prompt caching","Token budget allocation by priority","Context compression: summaries, pruning stale tool output","Output token reservation","Cost per task vs cost per call","Context rot in long windows"]),
 [Q("A 32k window reserves 4k for output and 5k for system and tools. Retrieval gets 60% of the rest. How many tokens is that?",["13,800","19,200","16,200","23,000"],0,"32,000 − 4,000 − 5,000 = 23,000; 60% of 23,000 = 13,800."),
  Q("Why put the stable system prompt and tool schemas first?",["Models ignore the end","It maximizes prompt-cache prefix hits","It shortens output","It is required by JSON"],1,"Caches match on identical prefixes, so stable content goes first.")],
 [R("Anthropic: Effective context engineering for AI agents","https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents"),R("Anthropic prompt caching docs","https://docs.anthropic.com/en/docs/build-with-claude/prompt-caching")],["context-budget"]),
"e-rag":(T("e-rag-x2","Agentic RAG: query rewriting, self-correction and abstention","Agentic RAG puts the model in control of retrieval. Rewrite the query first: expand acronyms, split multi-part questions, or generate a hypothetical answer to embed (HyDE). Use hybrid search (BM25 plus vectors) and contextual retrieval, which prepends a short chunk-specific context before embedding. Then grade the retrieved chunks. Corrective RAG (CRAG) rewrites and re-searches or falls back to web search when the grades are low, and Self-RAG trains the model to critique its own retrieval and support. If evidence stays weak after a capped number of retries, abstain and say what is missing.",["Query rewriting, decomposition and HyDE","Contextual retrieval and hybrid search","Relevance grading of retrieved chunks","CRAG and Self-RAG self-correction loops","Abstention with retry caps"]),
 [Q("First-pass retrieval is relevant 70% of the time, and one rewrite fixes half of the failures. What is the success rate after one retry?",["85%","77%","100%","70%"],0,"0.70 + 0.30 × 0.5 = 0.85."),
  Q("What should an agentic RAG system do when evidence is still weak after its retry cap?",["Answer anyway, confidently","Abstain and state what is missing","Raise temperature","Retry forever"],1,"Bounded retries followed by abstention prevent unsupported answers.")],
 [R("Anthropic: Introducing contextual retrieval","https://www.anthropic.com/news/contextual-retrieval"),R("Corrective RAG (CRAG) paper (arXiv)","https://arxiv.org/abs/2401.15884"),R("Self-RAG paper (arXiv)","https://arxiv.org/abs/2310.11511"),R("LangGraph agentic RAG tutorial","https://langchain-ai.github.io/langgraph/tutorials/rag/langgraph_agentic_rag/")],["agentic-rag-loop"]),
"g-mcp":(T("g-mcp-x1","MCP on the wire: raw JSON-RPC without an SDK","MCP messages are JSON-RPC 2.0: a request has jsonrpc, id, method and params; a response echoes the id with result or error; a notification has no id. A session starts with initialize, where client and server exchange protocol version and capabilities, then the client sends notifications/initialized. After that come tools/list, tools/call, resources/read and prompts/get. Over stdio, each message is one newline-delimited JSON line. Streamable HTTP uses POST, with optional SSE streams. Writing a 100-line server by hand teaches you what the SDKs do for you.",["JSON-RPC 2.0 requests, responses, notifications","initialize handshake and capability negotiation","tools/list and tools/call payloads","stdio framing vs Streamable HTTP","Error codes and cancellation"]),
 [Q("What makes a JSON-RPC notification different from a request?",["It has no id and expects no response","It uses XML","It must be batched","It has a result field"],0,"Notifications omit id, so no response is sent."),
  Q("Which message must come first in an MCP session?",["tools/call","initialize","resources/read","ping"],1,"Clients start with initialize to negotiate the version and capabilities.")],
 [R("MCP specification","https://modelcontextprotocol.io/specification/2025-06-18"),R("JSON-RPC 2.0 specification","https://www.jsonrpc.org/specification")],[]),
"e-prod":(T("e-prod-x1","Real-time streaming UX: SSE, WebSockets, optimistic UI","Users judge AI apps by time to first token. Server-Sent Events stream tokens one way over HTTP and suit most chat. WebSockets are two-way and suit voice and collaborative apps. For voice, add voice activity detection and barge-in, which cancels TTS and generation when the user speaks. Stream tool calls too: show 'searching…' as soon as the call is emitted, and render partial JSON arguments carefully. Optimistic UI shows the user's action immediately and reconciles later. Always handle reconnects, cancellation and backpressure.",["SSE vs WebSockets","Time to first token and perceived latency","Streaming tool calls and partial JSON","Barge-in and VAD for voice","Optimistic UI and reconciliation","Cancellation and reconnects"]),
 [Q("A chat app only needs to stream from server to client over HTTP. What is the simplest fit?",["WebSockets","Server-Sent Events","Polling every 10 s","gRPC bidirectional"],1,"SSE is a simple one-way HTTP stream."),
  Q("What is barge-in?",["Cancelling playback and generation when the user starts speaking","Batching requests","A caching layer","Token shuffling"],0,"Barge-in lets users interrupt a voice agent.")],
 [R("MDN: Using server-sent events","https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events/Using_server-sent_events"),R("MDN: WebSockets API","https://developer.mozilla.org/en-US/docs/Web/API/WebSockets_API"),R("OpenAI streaming responses guide","https://platform.openai.com/docs/guides/streaming-responses")],[]),
"e-llmops":(T("e-llmops-x1","Graceful degradation and fallback chains","Plan for outages, rate limits and budget overruns before they happen. A fallback chain tries a frontier model, then a mid-tier model, then a local model, then a semantic cache or a canned answer. Each step triggers on errors, timeouts or a budget signal. Cost kill switches watch spend per tenant and per feature, and step down tiers or disable expensive features at thresholds. Tell users when quality is degraded, log which tier served each request, and test the chain with chaos drills.",["Fallback chain: frontier, mid, local, cache","Triggers: errors, timeouts, rate limits, budget","Cost kill switches per tenant and feature","Degraded-mode UX messaging","Chaos drills for the chain"]),
 [Q("Frontier and mid-tier providers fail independently, 2% and 1% of the time. How often are both down?",["0.02%","3%","1%","0.2%"],0,"0.02 × 0.01 = 0.0002 = 0.02%."),
  Q("Which signal should step traffic down to a cheaper tier even when nothing is failing?",["A budget threshold from a cost kill switch","Higher user satisfaction","Lower latency","A new deploy"],0,"Budget triggers enforce FinOps limits.")],
 [R("LiteLLM: fallbacks and reliability","https://docs.litellm.ai/docs/proxy/reliability"),R("AWS Well-Architected: graceful degradation","https://docs.aws.amazon.com/wellarchitected/latest/reliability-pillar/rel_mitigate_interaction_failure_graceful_degradation.html")],["fallback-chain"]),
"e-datafly":(T("e-datafly-x1","DPO feedback flywheel end to end","A preference flywheel turns user feedback into training data. Log every response with the prompt, context and model version. When a user gives a thumbs-down and then accepts an edited or regenerated answer, that pair becomes a chosen and rejected example. Filter the pairs for PII, spam and label noise, deduplicate, and hold out an eval split. A nightly job trains a LoRA adapter with DPO, and the adapter is promoted only if offline evals and a shadow or canary test beat the current version.",["Logging prompts, context, versions","Turning thumbs-down and edits into preference pairs","Filtering, PII scrubbing, deduplication","Nightly LoRA + DPO training jobs","Eval gates, shadow and canary promotion"]),
 [Q("What does a DPO training example contain?",["A prompt plus a chosen and a rejected response","Only a reward score","Only images","A SQL query"],0,"DPO learns from preference pairs."),
  Q("When should a nightly adapter be promoted?",["Always, automatically","Only after it beats the current model on offline evals and a shadow or canary test","When the loss is lowest","When it is newest"],1,"Gates prevent regressions.")],
 [R("DPO paper (arXiv)","https://arxiv.org/abs/2305.18290"),R("Hugging Face TRL DPO Trainer","https://huggingface.co/docs/trl/dpo_trainer")],["rlhf-dpo-grpo"]),
"a-sys":(T("a-sys-x1","ADRs, teardowns and public benchmarks","Architecture Decision Records are short documents: context, decision, alternatives considered, and consequences. Each one is numbered and immutable, and a later record supersedes it rather than editing it. Write ADRs for model choice, retrieval design and fallback policy. Public teardowns show a hiring manager how you think: the problem, the architecture, the eval results with numbers, the costs, what failed and what you would change. Publish reproducible benchmarks with the dataset, harness and settings so others can rerun them.",["ADR template: context, decision, consequences","Superseding instead of editing","Writing a system teardown","Reproducible benchmark write-ups","Portfolio as evidence of judgment"]),
 [Q("How is an accepted ADR changed when the decision changes?",["Edit it in place","Write a new ADR that supersedes it","Delete it","Rename it"],1,"ADRs are immutable; new records supersede old ones."),
  Q("What makes a public benchmark credible?",["Only a chart","The dataset, harness and settings are published so others can reproduce it","High numbers","A logo"],1,"Reproducibility is the bar.")],
 [R("ADR GitHub organization","https://adr.github.io/"),R("Michael Nygard: Documenting architecture decisions","https://cognitect.com/blog/2011/11/15/documenting-architecture-decisions")],[]),
"g-mem":(T("g-mem-x1","Three-tier memory with scoring and eviction","Split agent memory into tiers. Working memory is the current context. Episodic memory stores past interactions and events with timestamps. Semantic memory holds distilled facts and preferences. Score each item for retrieval by a mix of relevance, recency and importance. The Generative Agents paper used a weighted sum with exponential recency decay. Evict or summarize low-score items, merge duplicates, and resolve contradictions by preferring newer, confirmed facts. Let users view and delete what is stored.",["Working, episodic and semantic tiers","Relevance, recency and importance scoring","Eviction and consolidation","Contradiction resolution","User-visible memory controls"]),
 [Q("With recency decay of 0.99 per hour, what is a memory's recency weight after 100 hours?",["About 0.37","0.99","0.01","1.0"],0,"0.99^100 ≈ 0.366.")],
 [R("Generative Agents paper (arXiv)","https://arxiv.org/abs/2304.03442")],[]),
}
CONCEPTS=[
dict(id="context-budget",title="Context Token Budget Allocator",trackHints=["engineer","agentic"],summary="Split the context window by priority so that the important content always fits and the bill stays predictable.",
body="A context window is a budget. Spend it in this order. First reserve output tokens so the answer is never truncated. Next come fixed costs: the system prompt and tool schemas, which are stable and placed first so prompt caching applies. The rest is shared by priority among retrieved evidence, recent conversation, and long-term memory.\n\nWhen a bucket overflows, compress it instead of truncating blindly. Summarize old turns, drop stale tool outputs, rerank and cut retrieved chunks, but keep IDs and numbers verbatim.\n\nCommon mistakes: no output reserve, putting variable content before stable content (which breaks caching), and filling the window just because it is there. Long contexts degrade recall, so smaller and relevant usually beats bigger.\n\nMental model: a budget allocator that runs before every call and logs what it dropped.",
mermaid="flowchart TD\n  W[Window 32k] --> O[Reserve output 4k]\n  W --> F[Fixed: system + tools 5k]\n  W --> V[Variable 23k]\n  V --> RET[Retrieval 60%: 13.8k]\n  V --> HIS[History 30%: 6.9k]\n  V --> MEM[Memory 10%: 2.3k]\n  HIS -->|overflow| SUM[Summarize old turns]\n  RET -->|overflow| RR[Rerank and cut]",
example="Window 32,000. Output reserve 4,000. System prompt and tools 5,000. Variable 32,000 − 9,000 = 23,000. Retrieval 60% = 13,800, history 30% = 6,900, memory 10% = 2,300; 13,800 + 6,900 + 2,300 = 23,000. Input is at most 28,000 tokens; at $3 per 1M input tokens that is $0.084 per call. If 5,000 cached prefix tokens bill at 10%, input cost becomes (23,000 × $3 + 5,000 × $0.30)/1M = $0.069 + $0.0015 = $0.0705."),
dict(id="agentic-rag-loop",title="Agentic RAG Self-Correction Loop",trackHints=["engineer","agentic"],summary="Rewrite, retrieve, grade, retry or abstain: a bounded loop that turns retrieval failures into recoveries or honest 'I don't know' answers.",
body="Plain RAG retrieves once and hopes. Agentic RAG adds control. Rewrite or decompose the query, run hybrid retrieval over contextually enriched chunks, then grade the results for relevance. If the grades pass, generate an answer with citations and optionally check that every claim is supported. If they fail, rewrite and retry, or route to another source such as web search (the CRAG pattern). After a fixed retry cap, abstain.\n\nCommon mistakes: unbounded loops, graders that are never themselves evaluated, and retrying with the same query. Track per-stage metrics: first-pass hit rate, recovery rate, abstention rate, and accuracy on answered questions.\n\nMental model: a thermostat for evidence quality, with a hard stop.",
mermaid="flowchart LR\n  Q[Question] --> RW[Rewrite / decompose]\n  RW --> RT[Hybrid retrieve]\n  RT --> G{Grade relevance}\n  G -->|pass| GEN[Generate with citations]\n  GEN --> SUP{Claims supported?}\n  SUP -->|yes| A[Answer]\n  SUP -->|no| RW\n  G -->|fail, retries left| RW\n  G -->|fail, cap reached| AB[Abstain: say what is missing]",
example="Suppose first-pass retrieval is good 70% of the time and each rewrite recovers half of the remaining failures. After one retry: 0.70 + 0.30 × 0.5 = 0.85. After two: 0.85 + 0.15 × 0.5 = 0.925. Abstention is 7.5%. Cost: if each attempt is 1 retrieval plus a 2k-token grading call, expected grading calls = 1 + 0.30 + 0.15 = 1.45 per question, so grading adds 2,900 tokens on average."),
dict(id="fallback-chain",title="Fallback and Degradation Chain",trackHints=["engineer","infra","architect"],summary="Frontier, then mid, then local, then cache: keep serving through outages and budget limits, at a known quality and cost.",
body="A degradation chain defines what happens when the preferred model is unavailable, too slow, or too expensive. Each tier has a trigger: errors, timeouts, rate limits, or a budget threshold from a cost kill switch. Lower tiers are cheaper and usually worse, so each tier has its own eval score, and you choose which features may degrade. For example, summaries can drop to a local model, but legal answers should abstain instead.\n\nCommon mistakes: fallbacks that are never tested, correlated providers (two models on the same cloud region), and silent degradation. Tell users, log the tier, and run chaos drills.\n\nMental model: a circuit breaker plus a price ladder.",
mermaid="flowchart LR\n  R[Request] --> C{Semantic cache hit?}\n  C -->|yes| OUT[Response]\n  C -->|no| F[Frontier]\n  F -->|ok| OUT\n  F -->|error / timeout / budget| M[Mid-tier]\n  M -->|ok| OUT\n  M -->|fail| L[Local model]\n  L -->|ok| OUT\n  L -->|fail| D[Canned answer + degraded notice]\n  OUT --> LOG[(Tier, cost, quality logs)]",
example="1M requests per month × 1,000 tokens = 1B tokens. All frontier at $10/M = $10,000. In degraded mode after the 80% budget kill switch: 30% cache hits ($0), 50% mid-tier at $1/M (0.5B tokens = $500), 20% frontier for critical features (0.2B = $2,000), total $2,500, 75% cheaper. Availability with independent failures, frontier 2% and mid 1%: both down 0.02 × 0.01 = 0.02% of the time, and the local tier covers that."),
]
